<script setup lang="ts">
import { computed } from 'vue'
import { hasRenderableContent } from '../../utils/vnode'
import { resolvePropValue } from '../../utils/resolvePropValue'
import type { ItemListRowProps, ItemListSize } from './types'

const props = withDefaults(defineProps<ItemListRowProps>(), {
  as: 'div',
  size: 'sm',
  active: false,
  selected: false,
  disabled: false,
})

const isEmphasized = computed(() => {
  return props.active || props.selected
})

const sizeClassMap: Record<ItemListSize, string> = {
  xs: 'min-h-6 px-1.5 py-1 text-xs',
  sm: 'min-h-7 px-2 py-1.5 text-base',
  md: 'min-h-8 px-2.5 py-1.5 text-base',
  lg: 'min-h-10 px-3 py-2 text-lg',
}

const sizeClasses = computed(() => {
  return resolvePropValue(sizeClassMap, props.size, 'sm', {
    component: 'ItemListRow',
    prop: 'size',
  })
})

const stateClasses = computed(() => {
  if (props.disabled) {
    return 'cursor-not-allowed text-ink-gray-4'
  }

  return isEmphasized.value
    ? 'bg-surface-gray-3 text-ink-gray-8'
    : 'text-ink-gray-7'
})

defineSlots<{
  default?: () => any
  prefix?: () => any
  label?: () => any
  suffix?: () => any
}>()
</script>

<template>
  <component
    :is="as"
    data-slot="item-list-row"
    :data-size="size"
    :data-state="isEmphasized ? 'active' : 'inactive'"
    :data-disabled="disabled ? '' : undefined"
    :class="[
      'flex w-full items-center gap-2 rounded-4 transition-colors',
      sizeClasses,
      stateClasses,
    ]"
  >
    <div
      v-if="hasRenderableContent($slots.prefix?.())"
      data-slot="item-prefix"
      class="flex shrink-0 items-center justify-center"
    >
      <slot name="prefix" />
    </div>

    <div data-slot="item-label" class="min-w-0 flex-1 leading-tighter">
      <slot name="label">
        <slot />
      </slot>
    </div>

    <div
      v-if="hasRenderableContent($slots.suffix?.())"
      data-slot="item-suffix"
      class="flex shrink-0 items-center justify-center"
    >
      <slot name="suffix" />
    </div>
  </component>
</template>
